window.ScripturaLexicons.BDAG_PART_0359 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-01\" data-source=\"BDAG\" data-search=\"τίμιος, α, ον adjetivo precioso; custoso; respeitado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίμιος, α, ον</td><td>adjetivo</td><td>precioso; custoso; respeitado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-02\" data-source=\"BDAG\" data-search=\"τιμιότης, ητος, ἡ substantivo feminino riqueza; prosperidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμιότης, ητος, ἡ</td><td>substantivo feminino</td><td>riqueza; prosperidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-03\" data-source=\"BDAG\" data-search=\"Τιμόθεος, ου, ὁ nome próprio masculino Timóteo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τιμόθεος, ου, ὁ</td><td>nome próprio masculino</td><td>Timóteo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-04\" data-source=\"BDAG\" data-search=\"Τίμων, ωνος, ὁ nome próprio masculino Timão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τίμων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Timão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-05\" data-source=\"BDAG\" data-search=\"τιμωρέω verbo punir; castigar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμωρέω</td><td>verbo</td><td>punir; castigar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-06\" data-source=\"BDAG\" data-search=\"τιμωρητής, οῦ, ὁ substantivo masculino vingador; punidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμωρητής, οῦ, ὁ</td><td>substantivo masculino</td><td>vingador; punidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-07\" data-source=\"BDAG\" data-search=\"τιμωρία, ας, ἡ substantivo feminino castigo; punição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμωρία, ας, ἡ</td><td>substantivo feminino</td><td>castigo; punição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-08\" data-source=\"BDAG\" data-search=\"τίνω verbo pagar; sofrer pena BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίνω</td><td>verbo</td><td>pagar; sofrer pena</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-09\" data-source=\"BDAG\" data-search=\"τίς, τί pronome interrogativo quem?; qual?; quê?; por quê? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίς, τί</td><td>pronome interrogativo</td><td>quem?; qual?; quê?; por quê?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-10\" data-source=\"BDAG\" data-search=\"τὶς, τὶ, pronome indefinido alguém; algum; qualquer; algo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τὶς, τὶ,</td><td>pronome indefinido</td><td>alguém; algum; qualquer; algo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-11\" data-source=\"BDAG\" data-search=\"Τίτιος, ου, ὁ nome próprio masculino Tício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τίτιος, ου, ὁ</td><td>nome próprio masculino</td><td>Tício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-12\" data-source=\"BDAG\" data-search=\"τίτλος, ου, ὁ substantivo masculino inscrição; aviso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίτλος, ου, ὁ</td><td>substantivo masculino</td><td>inscrição; aviso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-13\" data-source=\"BDAG\" data-search=\"Τίτος, ου, ὁ nome próprio masculino Tito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τίτος, ου, ὁ</td><td>nome próprio masculino</td><td>Tito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-14\" data-source=\"BDAG\" data-search=\"τιτρώσκω verbo ferir; lesar; danificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιτρώσκω</td><td>verbo</td><td>ferir; lesar; danificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-15\" data-source=\"BDAG\" data-search=\"τοί partícula certamente; ademais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοί</td><td>partícula</td><td>certamente; ademais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-16\" data-source=\"BDAG\" data-search=\"τοιγαροῦν partícula inferencial portanto; por essa razão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοιγαροῦν</td><td>partícula inferencial</td><td>portanto; por essa razão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-17\" data-source=\"BDAG\" data-search=\"τοίνυν partícula inferencial pois bem; por conseguinte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοίνυν</td><td>partícula inferencial</td><td>pois bem; por conseguinte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-18\" data-source=\"BDAG\" data-search=\"τοιόσδε, άδε, όνδε adjetivo demonstrativo tal; deste gênero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοιόσδε, άδε, όνδε</td><td>adjetivo demonstrativo</td><td>tal; deste gênero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-19\" data-source=\"BDAG\" data-search=\"τοιοῦτος, αύτη, οῦτον adjetivo correlativo tal; semelhante; desta espécie BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοιοῦτος, αύτη, οῦτον</td><td>adjetivo correlativo</td><td>tal; semelhante; desta espécie</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0359-20\" data-source=\"BDAG\" data-search=\"τοῖχος, ου, ὁ substantivo masculino parede BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοῖχος, ου, ὁ</td><td>substantivo masculino</td><td>parede</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0359-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίμιος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίμιος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">τιμή</span>; Hom.+) geralmente ‘tido em honra’ (Herodas 4, 5, a respeito de altares)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a ser de valor excepcional</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> custoso, precioso Plut., Mor. 486b <span class=\"greek\">λίθος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>; 18:12a, 16; 21:19; AcPl Ha 1, 11 (cf. Tob 13:17 S; JosAs 2:3; 18:4). Superl. (Jos., Ant. 17, 225 <span class=\"greek\">φίλον</span> <span class=\"greek\">τιμιώτατον</span>) <span class=\"greek\">λίθος</span> <span class=\"greek\">τιμιώτατος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:11</a>. Pl. <span class=\"greek\">λίθοι</span> <span class=\"greek\">τίμιοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:12</a> (v. <span class=\"greek\">λίθος</span> 2b e a literatura s.v. <span class=\"greek\">ἀμέθυστος</span>). <span class=\"greek\">ξύλον</span> <span class=\"greek\">τιμιώτατον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:12b</a> (sobre o valor elativo, v. Mussies 71, 128). <span class=\"greek\">τίμια</span> <span class=\"greek\">ἀρώματα</span> MPol 15:2.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de grande valor, precioso, a respeito do sangue de Jesus <span class=\"greek\">τίμιον</span> <span class=\"greek\">αἷμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:19</a>; <span class=\"greek\">τίμιον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> precioso para Deus 1 Cl 7:4. <span class=\"greek\">τίμιος</span> <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τίμια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέγιστα</span> <span class=\"greek\">ἐπαγγέλματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:4</a>. <span class=\"greek\">τιμίαν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">νηστείαν</span> AcPl Ha 6, 24. Comp. <span class=\"greek\">τιμιώτερος</span> com gen. (Eur., Alc. 301; Menand., Mon. 482; 552 Meinecke [715; 843 Jaekel]): a respeito dos ossos de um mártir <span class=\"greek\">τιμιώτερα</span> <span class=\"greek\">λίθων</span> <span class=\"greek\">πολυτελῶν</span> (Pr 3:15; ApcEsdr 6:15 p. 33, 2 Tdf. <span class=\"greek\">τὸ</span> <span class=\"greek\">τίμιον</span> … <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σῶμα</span>) MPol 18:1. A respeito do <span class=\"greek\">δοκίμιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>: <span class=\"greek\">πολὺ</span> <span class=\"greek\">τιμιώτερον</span> <span class=\"greek\">χρυσίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a> v.l. (sobre <span class=\"greek\">τιμιώτερον</span> <span class=\"greek\">χρυς</span>. cf. Diog. L. 8, 42; EpArist 82; Philo, Sacr. Abel. 83, Det. Pot. Ins. 20; Theophyl. Sim., Ep. 81; cf. PsSol 17:43 <span class=\"greek\">χρυσίον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τίμιον</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> tido em honra, respeitado (<span class=\"greek\">τιμή</span> 2c) <span class=\"greek\">τίμιος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">γάμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> Para <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">ποιοῦμαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">τιμίαν</span> <span class=\"greek\">ἐμαυτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:24</a> cf. <span class=\"greek\">λόγος</span> 1a<span class=\"greek\">α</span>, final.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a uma posição elevada que merece estima, tido em honra/em grande consideração, respeitado (frequentemente nas saudações de cartas em papiro; cf. a saudação <span class=\"greek\">τιμιώτατε</span> <span class=\"greek\">πάτερ</span> TestAbr A 2 p. 78, 21 [Stone p. 4]; <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀβραάμ</span> 7 p. 84, 24 [St. p. 16] e <span class=\"greek\">τίμιε</span> <span class=\"greek\">Ἀβραάμ</span> 16 p. 97, 21 [St. p. 42]) <span class=\"greek\">τινί</span> por alguém (Jos., Bell. 5, 527 <span class=\"greek\">τῷ</span> <span class=\"greek\">δήμῳ</span> <span class=\"greek\">τίμιος</span>, Ant. 1, 273) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:34</a>; 17:34 v.l.—DELG s.v. <span class=\"greek\">τιμή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμιότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμιότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τίμιος</span>; Aristot. et al.; em papiros como título honorífico) riqueza, prosperidade, abstrato pelo concreto: abundância de coisas preciosas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:19</a>.—DELG s.v. <span class=\"greek\">τιμή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τιμόθεος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τιμόθεος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (encontrado frequentemente Aristoph., X.+; inscrições, papiros, LXX; Jos., Ant. 12, 329–44) voc. <span class=\"greek\">Τιμόθεε</span> 1 Ti 1:18; 6:20. Timóteo, amigo, companheiro de viagem e colaborador de Paulo. Ac 16:1ss informa-nos que vivia na Licaônia, provavelmente em Listra, e que nascera de pai politeísta e mãe monoteísta (chamada Eunice segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a>). Paulo mandou circuncidá-lo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:3</a>) antes de levá-lo consigo numa de suas importantes viagens (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:19</a>; Ac 17:14s; 18:5) e serviu-se dele permanentemente como colaborador (<span class=\"greek\">συνεργός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:21</a>). É mencionado como ‘coautor’ de seis cartas (2 Cor 1:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:1</a>; Phlm 1). Atuou em Tessalônica (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>, 6; v. a subscrição de 2 Th), Corinto (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>; 16:10) e depois novamente na Macedônia (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:22</a>), como enviado de Paulo. Também o acompanhou em sua última viagem a Jerusalém (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a>). Mais tarde compartilhou a prisão de Paulo (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:19</a> e também as introduções das epístolas do cativeiro, exceto Eph). Em 1 e 2 Ti é mencionado nas saudações (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:2</a>) e também em 1 Ti 1:18; 6:20 (v. acima, início); a subscrição de 2 Ti refere-se a ele como bispo. Finalmente aparece mais uma vez no NT, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:23</a>. Não é mencionado em nenhum outro lugar de nossa literatura.—AJülicher, RE XIX 1907, 781–88; FPölzl, Die Mitarbeiter des Weltap. Pls 1911, 136ff; ERedlich, St. Paul and His Companions 1913; WHadorn (s.v. <span class=\"greek\">ὑπηρέτης</span>); JAlexander, The Character of Tim.: ET 25, 1914, 277–85 (contra ele GFindlay, ibid. 426); Pauly-W. VI A ’37, 1342–54; Kl. Pauly V 851f; BHHW III, 1988–91; WOllrog, Paulus u. s. Mitarbeiter ’79; PTrümert, Die Paulustrad. d. Past. ’78. Sobre a composição e a linguagem das Pastorais, v. PHarrison, The Problem of the Pastoral Epistles 1921; BEaston, The Pastoral Epistles ’47; comentário abrangente de CSpicq ’47; MDibelius e HConzelmann, The Pastoral Epistles (trad. inglesa) ’72; JWhite, New Testament Epistolary Lit. in the Framework of Ancient Epistolography, ANRW II/25/2 ’84, 1730–56. V. também WKümmel, Einleitung21 ’83 —DELG s.v. <span class=\"greek\">τιμή</span>. LGPN I. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τίμων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τίμων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (frequente na literatura, inscrições, papiros) Timão, uma das sete pessoas designadas para liberar os apóstolos do trabalho burocrático relativo à assistência às viúvas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a> (sobre o assunto, cf. Ex 18:13–27).—DELG s.v. <span class=\"greek\">τιμή</span>. LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμωρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμωρέω</span> (<span class=\"greek\">τιμωρό</span> ‘vingador’, de <span class=\"greek\">τιμή</span> + uma raiz or [como no dór. <span class=\"greek\">τιμάορος</span>, Pind. O. 9, 84, mas ali no sentido de ‘prestar honra a’]) 1 aor. <span class=\"greek\">ἐτιμώρησα</span> Wsd 12:20; perf. 2 pl. <span class=\"greek\">τετιμωρήκατε</span> (Tat. 27, 1). Méd.: fut. <span class=\"greek\">τιμωρήσομαι</span> LXX; 1 aor. <span class=\"greek\">ἐτιμωρησάμην</span> LXX. Pass.: 1 aor. <span class=\"greek\">ἐτιμωρήθην</span>; perf. 3 sing. <span class=\"greek\">τετιμώρηται</span> 4 Macc 18:5, partic. <span class=\"greek\">τετιμωρημένος</span> (TestSol 5:3) (Trag., Hdt. et al.; inscrições, papiros, LXX, En; ParJer 7:26) punir <span class=\"greek\">τινά</span> alguém, mandar punir alguém (Soph., Oed. Rex 107; Lysias 13, 41; 42; Jos., Ant. 2, 107; 7, 93; TestJos 14:1; Just.; Tat. 27, 1. Mas a voz média é muito mais amplamente empregada nesse sentido [é habitual em Philo; Jos., Ant. 1, 195; 17, 211]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:11</a>. <span class=\"greek\">τιμωρεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">δειναῖς</span> <span class=\"greek\">τιμωρίαις</span> punir alguém com castigos terríveis Hs 6, 3, 3. Pass. (X., An. 2, 5, 27; Pla., Gorg. 81, 525b; 2 Macc 7:7; En 22:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:5</a>; Hs 6, 3, 4; 6, 5, 3f; 6.—DELG s.v. <span class=\"greek\">τιμωρό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμωρητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμωρητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τιμωρέω</span>; 2 Macc 4:16; Philo, Rer. Div. Her. 109; PCairMasp 5, 16) vingador, punidor, a respeito do pastor que pune <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιμὴν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τιμωρητής</span> Hs 7:1 Joly. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τιμ</span>. 7:1, 6 (cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">τιμωρὸς</span> <span class=\"greek\">δαίμων</span> Herm. Wr. 1, 23; Lydus, Mens. 90, 24).—DELG s.v. <span class=\"greek\">τιμωρό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμωρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμωρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (de <span class=\"greek\">τιμωρό</span> ‘vingador’, v. <span class=\"greek\">τιμωρέω</span>) castigo (Aeschyl., Hdt.+) em nossa literatura, infligido por Deus (Theopompus [IV a.C.]: 115 Fgm. 253, p. 590, 29 Jac. <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τιμ</span>.; Eth. Epic. col. 12, 7 <span class=\"greek\">τιμ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεῶν</span>; Diod S 13, 21, 1 <span class=\"greek\">τιμ</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῶν</span>; 16, 64, 1; Aesop, Fab. 1 P.=5 H. <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τιμ</span>. Cf. Jos., Bell. 2, 155 <span class=\"greek\">τιμωρίαι</span> <span class=\"greek\">ἀδιάλειπτοι</span>) B 20:1; Hs 6, 3, 2b; 6, 4, 4; 6, 5, 3ab. <span class=\"greek\">πόσῳ</span> <span class=\"greek\">δοκεῖτε</span> <span class=\"greek\">χείρονος</span> <span class=\"greek\">ἀξιωθήσεται</span> <span class=\"greek\">τιμωρίας</span>; quanto mais severo castigo, pensais, será decretado para … ? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a> (Diod S 4, 12, 7 <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">τιμωρίας</span> <span class=\"greek\">ἠξιώθη</span>=cada um teve um castigo infligido a si; 16, 31, 2; 16, 46, 3). Pl. (Pla., Ep. 7, 335a <span class=\"greek\">μεγίστας</span> <span class=\"greek\">τ</span>. [de Deus]; Diod S 1, 96, 5 <span class=\"greek\">τὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀσεβῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾅδου</span> <span class=\"greek\">τιμωρίας</span>; Plut., Mor. 566e [no mundo inferior]; LXX; TestJos 3:1; EpArist 208; Philo; Jos., C. Ap. 2, 292; Just., A II, 20, 4 al.; Tat. 17, 1) Hs 6, 3, 3; 4ab; 6, 5, 7. <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλὰς</span> … <span class=\"greek\">βασάνους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμωρίας</span> Papias (3:3). <span class=\"greek\">τιμωρίαν</span> <span class=\"greek\">ὑπέχειν</span> sofrer castigo (escólio sobre Soph., Oed. Col. 1565 p. 460 Papag.; Ath. 2, 1) MPol 6:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τιμωρίας</span> o anjo que pune (v. <span class=\"greek\">τιμωρητής</span>) Hs 6, 3, 2a; 7:2 (Leutzsch, Hermas 476 n. 157).—DELG s.v. <span class=\"greek\">τιμωρό</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίνω</span> (Hom. et al.; PHamb 22, 5; Just., A I, 17, 1) fut. <span class=\"greek\">τίσω</span> (melhor <span class=\"greek\">τείσω</span>: Kühner-Bl. II 552; Mayser 91, 2; B-D-F §23; Mlt-H. 261) experimentar retribuição, pagar, sofrer uma pena <span class=\"greek\">δίκην</span> <span class=\"greek\">τίνειν</span> (desde Soph., Aj. 113; v. <span class=\"greek\">δίκη</span> 1; Pr 27:12 <span class=\"greek\">ζημίαν</span> <span class=\"greek\">τείσουσιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:9</a>; Hm 2:5; Hs 9, 19, 3.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίς, τί</h1><div class=\"entry-meta\"><span>pronome interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίς</span>, <span class=\"greek\">τί</span> gen. <span class=\"greek\">τίνος</span>, dat. <span class=\"greek\">τίνι</span>, acus. <span class=\"greek\">τίνα</span>, <span class=\"greek\">τί</span> (Hom.+) pron. interrogativo em perguntas diretas, indiretas e retóricas (W-S. §25, 1ff; B-D-F §298f, al.; Rob. 735–40 al.)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> referência interrogativa a alguém ou alguma coisa, quem? qual? quê?</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> como subst.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">τίς</span>;</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . quem? qual? <span class=\"greek\">τίς</span> <span class=\"greek\">ὑπέδειξεν</span> <span class=\"greek\">ὑμῖν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:7</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παίσας</span> <span class=\"greek\">σε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:68</a> (FNeirynck, ETL 63, 5–47; RBrown, The Death of the Messiah ’94, II 578–80). <span class=\"greek\">τίνος</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">ἐστιν</span>; de quem é filho? 22:42b. <span class=\"greek\">τίνα</span> <span class=\"greek\">λέγουσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span>; 16:13. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:28</a>; 12:16; 16:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:9</a>, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:4</a>, 7 (cf. Jos., Ant. 9, 56). <span class=\"greek\">τίς</span> <span class=\"greek\">σοφὸς</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:13</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐστιν</span>; quem, então, é ela? Hs 2, 4, 1.—Especialmente em perguntas para as quais se espera a resposta ‘ninguém’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:33</a> (Is 53:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:24</a>; 8:24, 33–35; 9:19b; 10:16 (Is 53:1); 11:34ab (Is 40:13ab); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7abc</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:29ab</a>. Igualmente <span class=\"greek\">τίς</span> … <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span>; quem … exceto, senão? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:22</a>; 5:5 (PsSol. 5:3, 11). Pl. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τίνες</span> <span class=\"greek\">ἐστέ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:15</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:16–18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:13</a>.—Seguido de gen. partitivo (JosAs 6:7 [<span class=\"greek\">τίς</span> … <span class=\"greek\">ἀνθρώπων</span>;]; Ar. 9, 5; Tat. 2, 1) <span class=\"greek\">τίς</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τριῶν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:36</a>. <span class=\"greek\">τίνος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">υἱός</span>; 14:5. <span class=\"greek\">τίνι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5</a>. <span class=\"greek\">τίνα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:52</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a> al. Em lugar do gen. partitivo <span class=\"greek\">τίς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span>; etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:5</a>; 14:28.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:31</a>. <span class=\"greek\">τίνα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:21</a>.</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . quem? no sentido de que espécie de pessoa? (=<span class=\"greek\">ποῖος</span>; cf. Ex 3:11; Jdth 12:14; Jos., Ant. 6, 298; Ath. 12, 2) <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">βλασφημίας</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:21a</a>. Cf. 19:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:17</a> (cf. 4 Km 8:13); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:5ab</a> v.l. (em ambos); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:12</a>. <span class=\"greek\">σὺ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">εἶ</span>; quem és tu (afinal)? que espécie de pessoa és? (Menand., Epitr. 391 S. [215 Kö.]; Epict. 3, 1, 22; 23; Herm. Wr. 1, 2; Job 35:2; Tat. 6, 2 <span class=\"greek\">τίς</span> <span class=\"greek\">ἤμην</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγίνωσκον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a>; 8:25; 21:12. <span class=\"greek\">τίς</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὅτι</span> quem sou eu, para que GJs 12:2 (Ex 3:11).</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . qual de dois? (=<span class=\"greek\">πότερος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:2</a>.</p><p class=\"entry-text\"><span class=\"hebrew\">ד</span> . em substituição ao pron. relativo (Callimachus 28 [=30], 2; Ptolemaeus Euergetes em Athen. 10, 438e <span class=\"greek\">τίνι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τύχη</span> <span class=\"greek\">δίδωσι</span>, <span class=\"greek\">λαβέτω</span>. Cf. BGU 665 III, 13 [I d.C.]; 822, 4 [III d.C.] <span class=\"greek\">εὗρον</span> <span class=\"greek\">γεοργόν</span>, <span class=\"greek\">τίς</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">ἑλκύσῃ</span>; Gen 38:25; Lev 21:17; Dt 29:17; v. 1a<span class=\"greek\">β</span><span class=\"hebrew\">ו</span> abaixo e v. Kühner-G. II 517f; OImmisch, Leipz. Studien z. klass. Philol. 10, 1887, 309ff; KBuresch, RhM n.s. 46, 1891, 231ff; Mlt. 21 n. 1; 93f; Rob. 737f; Dssm., LO 266, 5 [CIG 9552—LAE 313, 6]; Mayser II/1, 1926, 80) <span class=\"greek\">τίνα</span> <span class=\"greek\">με</span> <span class=\"greek\">ὑπονοεῖτε</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ἐγώ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:25</a> v.l. Assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:13</a>, se a pontuação deve ser <span class=\"greek\">τίς</span> <span class=\"greek\">σοφὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">δειξάτω</span>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τί</span>;</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . quê? <span class=\"greek\">τί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">δοκεῖ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:25a</a>; cf. 18:12; 21:28. <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσει</span>; v. 40. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:33</a>; 10:3, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:22b</a>; 18:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:7b</a> al. <span class=\"greek\">τίνι</span>; a que (coisa)? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:18ab</a>; 20.—Com preposições: <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span>; por quê? por que razão? cf. <span class=\"greek\">διά</span> B 2b. <span class=\"greek\">εἰς</span> <span class=\"greek\">τί</span>; por quê? com que finalidade? <span class=\"greek\">εἰς</span> 4f. <span class=\"greek\">ἐν</span> <span class=\"greek\">τίνι</span>; com quê? por meio de quem? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; 12:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:19</a>; 14:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:9</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τί</span>; por quê? (X., Cyr. 6, 3, 20; 8, 4, 21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:28</a>. <span class=\"greek\">χάριν</span> <span class=\"greek\">τίνος</span>; por quê? lit. ‘por causa de que coisa?’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12</a> (cf. Just., A II, 12, 5; Tat. 34, 3).</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . que espécie de coisa? (=<span class=\"greek\">ποῖον</span>) <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τοῦτο</span>; que espécie de coisa é esta? (Ps.-Lucian, Halc. 1 <span class=\"greek\">τίς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνή</span>; Ex 16:15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a>. <span class=\"greek\">τί</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῦτος</span> que espécie de riqueza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:27</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:19</a>; 3:18.</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . qual de dois? (=<span class=\"greek\">πότερον</span>; Pla., Phlb. 52d) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:5</a>; 23:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:22</a>.</p><p class=\"entry-text\"><span class=\"hebrew\">ד</span> . <span class=\"greek\">τί</span> como pred. pode acompanhar um sujeito que esteja no pl. (Pla., Tht. 155c <span class=\"greek\">τί</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">ταῦτα</span>; [assim também TestAbr A 12 p. 91, 16=Stone p. 30, e TestLevi 2:9 v.l.]; Lucian, Dial. Deor. 11, 1; Synes., Prov. 2, 2 p. 118b; Laud. Therap. 18 <span class=\"greek\">τί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ταῦτα</span>; cf. TestAbr A 7 p. 83, 32 [Stone p. 14] <span class=\"greek\">τί</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁραθέντα</span>; GrBar 2:7 <span class=\"greek\">τί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">οὗτοι</span>; que significam estas pessoas? Jos., Vi. 296 <span class=\"greek\">τί</span> <span class=\"greek\">γεγόνασιν</span>;) ou que não seja de gênero neutro (B-D-F §299, 1; 2; Rob. 736; cf. X., Hell. 2, 3, 17 <span class=\"greek\">τί</span> <span class=\"greek\">ἔσοιτο</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πολιτεία</span>, Mem. 4, 2, 21; GrBar 6:13 <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">αὕτη</span>; ApcMos 5 <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πόνος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νόσος</span>;): <span class=\"greek\">τί</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">ἄνθρωπος</span>; (Epict. 2, 5, 26; 2, 9, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a> (Ps 8:5). <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσούτους</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>. <span class=\"greek\">ἐπυνθάνετο</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:26</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ἐσόμεθα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:2</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πέτρος</span> <span class=\"greek\">ἐγένετο</span> o que teria acontecido a Pedro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:18</a>. <span class=\"greek\">οὗτος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τί</span> (<span class=\"greek\">ἔσται</span>); e quanto a este homem? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:21</a>. Esta passagem constitui uma transição para</p><p class=\"entry-text\"><span class=\"hebrew\">ה</span> . expressões elípticas: <span class=\"greek\">τί</span> <span class=\"greek\">οὐν</span>; (X., Mem. 4, 2, 17; Teles p. 25, 13; Diod S 13, 26, 1; Ael. Aristid. 28, 17 K.=49 p. 496 D.; escólio sobre Pind., O. 12, 20c; Jos., Bell. 2, 364; Just., D. 3, 6; Ath. 15, 1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:15</a>, 26 a expressão é dada mais plenamente <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐστιν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:1</a>; 7:7; 9:14, 30 <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἐροῦμεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:19</a> <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">φημι</span>;) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:9</a>; 6:15 (Seneca, Ep. 47, 15 também introduz uma inferência absurda com ‘quid ergo’); 11:7.—<span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span>; qual é, então, a situação? (Ps.-Pla., Erx. 1, 392b; Diod S 34 + 35 Fgm. 2, 38; Dio Chrys. 71 [21], 16; Lucian, Tyrannic. 13; Just., D. 1, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:3</a>; que importa? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:18</a>. Também <span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">μοι</span> (TestJob 23:8 <span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θρίξ</span>) seguido de inf. é isso da minha conta? (Tat. 33, 2 <span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">μοι</span> … <span class=\"greek\">λέγειν</span> por que deveria eu despender tempo … em dizer alguma coisa?—cf. sem <span class=\"greek\">γάρ</span> Epict. 2, 17, 14 <span class=\"greek\">καὶ</span> <span class=\"greek\">τί</span> <span class=\"greek\">μοι</span>; 3, 22, 66 <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">σοι</span>; Maximus Tyr. 2, 10c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:12</a>.—Sobre <span class=\"greek\">τί</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span> (<span class=\"greek\">πρός</span> <span class=\"greek\">σε</span>); v. <span class=\"greek\">πρός</span> 3e<span class=\"greek\">γ</span>. Sobre <span class=\"greek\">τί</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοί</span>; v. <span class=\"greek\">ἐγώ</span>, final; também Schwyzer II 143; Goodsp., Probs. 98–101; MSmith, JBL 64, ’45, 512f; JLilly, CBQ 8, ’46, 52–57. <span class=\"greek\">τί</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοί</span>; tem o mesmo significado: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:24a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:34a</a> (cf. Epict. 2, 19, 16; 2, 20, 11).—<span class=\"greek\">τί</span> <span class=\"greek\">ὅτι</span>;=<span class=\"greek\">τί</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ὅτι</span>; (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:22</a>) o que aconteceu para que? por quê? (LXX; JosAs 16:5 <span class=\"greek\">τί</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">εἶπας</span> … ;) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:16</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>, 9; Hs 9, 5, 2.—Sobre <span class=\"greek\">ἵνα</span> <span class=\"greek\">τί</span> v. o artigo <span class=\"greek\">ἱνατί</span>.</p><p class=\"entry-text\"><span class=\"hebrew\">ו</span> . em substituição ao relativo (SIG 543, 12; 705, 56; 736, 50; v. a<span class=\"greek\">α</span><span class=\"hebrew\">ד</span> acima) <span class=\"greek\">οὐ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">σύ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:36</a>. Cf. 4:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:25</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:7</a>.—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">τί</span> <span class=\"greek\">φάγωσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:2</a> (cf. v. 1) provavelmente deve ser entendido como pergunta indireta=‘não sabem o que hão de comer’ (W-S. §24, 17b).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Dois pronomes interrogativos aparecem juntos sem conjunção (distributivo; v. Kühner-G. II 521f; B-D-F §298, 5; Rob. 737) <span class=\"greek\">τίς</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἄρῃ</span> o que cada um deveria receber <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:24</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">τί</span> <span class=\"greek\">διεπραγματεύσατο</span> o que cada um ganhou negociando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:15</a> v.l. Cf. Hv 3, 8, 6; m 6, 1, 1 (v. também Ael. Aristid. 31 p. 598 D.: <span class=\"greek\">τί</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">λέγοι</span>; Ps.-Clem., Hom. 2, 33).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> como adj. (TestAbr A 15 p. 96, 15 [Stone p. 40] <span class=\"greek\">τί</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">γενήσεται</span>; TestJob 47:1 <span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">χρεία</span>; ApcEsdr 5:26 p. 30, 30 Tdf. <span class=\"greek\">τίς</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">ἄνθρωπος</span>; Just., A I, 53, 2 al.) <span class=\"greek\">τίνα</span> que (espécie de) <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἔχετε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:46</a>. <span class=\"greek\">τίς</span> <span class=\"greek\">βασιλεύς</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31</a>. Cf. 15:4, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:18</a>; 18:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:14–16</a> (cinco vezes). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:2</a> <span class=\"greek\">οἰδατε</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">παραγγελία</span> pois sabeis quais instruções (vos demos). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a> <span class=\"greek\">τί</span> substitui <span class=\"greek\">ποῖο</span> (conforme a leitura de D, segundo Is 66:1); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a>, onde <span class=\"greek\">τί</span> e o subsequente <span class=\"greek\">ποῖο</span> são contrastados. <span class=\"greek\">τί</span> <span class=\"greek\">περισσόν</span>; etc.: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:47</a>; 19:16; 27:23.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> expressão interrogativa da razão de algo, por quê? adv. <span class=\"greek\">τί</span> (Hom., Pla., et al.; LXX; TestAbr A 8 p. 85, 23 [Stone p. 18]; B 7 p. 111, 4 [St. p. 70]; ApcEsdr 5:16 p. 30, 15 Tdf.; ApcSed 3:1; ApcMos 27; Just., A I, 20, 3; Tat. 10, 2; Ath. 17, 4) <span class=\"greek\">τί</span> <span class=\"greek\">μεριμνᾶτε</span>; por que vos preocupais? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>. Cf. 7:3; 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:7a</a>, 8; 4:40; 11:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:48</a>; 6:46; 19:33; 24:38a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:19</a>; 18:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:11</a>; 14:15; 26:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:7c</a>; 10:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:20</a>. <span class=\"greek\">τί</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἐποίησας</span>; GJs 13:2; 15:3 (GrBar 1:2 <span class=\"greek\">τί</span> <span class=\"greek\">ἐποίησας</span> <span class=\"greek\">τοῦτο</span>;). <span class=\"greek\">τί</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span>; por que, então, existe a lei=pois bem, para que serve a lei (mosaica)? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a>. <span class=\"greek\">τί</span> <span class=\"greek\">καί</span>; por quê, de fato? por que razão possível? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29b</a>, 30. <span class=\"greek\">τί</span> <span class=\"greek\">γινώσκω</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span>; como haveria eu de saber onde está meu filho? GJs 23:1.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> expressão exclamativa de extensão ou grau, como! adv. <span class=\"greek\">τί</span> (trad. do hebr. <span class=\"hebrew\">מָה</span>; W-S. §21, 4; B-D-F §299, 4; Rob. 739; 1176; LXX [Ps 3:2; SSol 1:10; 7:7; 2 Km 6:20]; Basilius, Hexaëm. p. 8b MPG <span class=\"greek\">τί</span> <span class=\"greek\">καλὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τάξις</span> [v. JTrunk, De Basilio Magno sermonis Attici imitatore: Wissensch. Beilage z. Jahresber. d. Gymn. Ehingen a. D. 1911, 36]) <span class=\"greek\">τί</span> <span class=\"greek\">στενή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a>; <span class=\"greek\">τί</span> <span class=\"greek\">θέλω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:49</a> (v. <span class=\"greek\">θέλω</span> 1, final, e Black, Aramaic Approach3, ’67, 121–24).—M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τὶς, τὶ,</h1><div class=\"entry-meta\"><span>pronome indefinido</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τὶς</span>, <span class=\"greek\">τὶ</span>, gen. <span class=\"greek\">τινός</span>, dat. <span class=\"greek\">τινί</span>, acus. <span class=\"greek\">τινά</span>, <span class=\"greek\">τὶ</span> (Hom.+) pronome indefinido enclítico (W-S. §26, 1–4; B-D-F §301 al.; Rob. 741–44)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> referência a alguém ou a alguma coisa indefinida, qualquer pessoa, qualquer coisa; alguém, alguma coisa; muitas pessoas/coisas, certa pessoa/coisa</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> subst.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">τὶς</span>, <span class=\"greek\">τινές</span></p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . alguém, qualquer pessoa, uma pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:29</a>, 47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:4</a>; 9:30; 11:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:46</a>; 9:57; 13:6, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:25</a>; 6:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:25</a>; 17:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:20</a> (cinco vezes); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:19</a> al. Pl. <span class=\"greek\">τινές</span> alguns, certo número de (pessoas — subentendidas como em Appian, Hann. 47 §203 <span class=\"greek\">λαβών</span> <span class=\"greek\">τινας</span>=recebeu alguns, isto é, pessoas; TestAbr B 14 p. 118, 20 [Stone p. 84]; TestJob 9:8; Just., A I, 28, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:11</a>; quaisquer pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:9b</a> (TestAbr B 12 p. 116, 24 [Stone p. 80] <span class=\"greek\">εἶδεν</span> … <span class=\"greek\">τινὰς</span> <span class=\"greek\">ἀπερχομένους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἔρημον</span> <span class=\"greek\">τόπον</span>).—Em contraste com uma maioria evidenciada pelo contexto, alguns dos presentes (Appian, Bell. Civ. 1, 26 §119 <span class=\"greek\">ἔφερόν</span> <span class=\"greek\">τινες</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:29a</a>; de todos (os considerados) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:7</a>; 9:22. <span class=\"greek\">ἀνατρέπουσιν</span> <span class=\"greek\">τήν</span> <span class=\"greek\">τινων</span> <span class=\"greek\">πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tim 2:18</a>; AcPlCor 1:2.—Com gen. partitivo (Diod S 2, 24, 4; Plut., Mor. 189a <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐχθρῶν</span> <span class=\"greek\">τις</span>; Epict. 2, 14, 1 <span class=\"greek\">τὶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ῥωμαϊκῶν</span>; TestReub 4:2 <span class=\"greek\">τινὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδελφῶν</span>; Ar. 12, 7 <span class=\"greek\">τινὲς</span> … <span class=\"greek\">αὐτῶν</span>; Just., A I, 27, 3; Tat. 36, 2) <span class=\"greek\">τὶς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Φαρισαίων</span> (algum) dos fariseus, um fariseu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:36</a>. Cf. 11:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a>. <span class=\"greek\">τὶς</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a>. Pl. <span class=\"greek\">τινὲς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γραμματέων</span> alguns (dos) escribas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:3</a>. Cf. 12:38; 28:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:1f</a>; 12:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:23</a>; 12:1; 17:18a, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:7–10</a> al.—Também <span class=\"greek\">τὶς</span> <span class=\"greek\">ἐκ</span> (Plut., Galba 1065 [27, 2]; Appian, Bell. Civ. 3, 84 §343 <span class=\"greek\">τὶς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βουλῆς</span>) <span class=\"greek\">τὶς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a>; GJs 24:2. Pl. <span class=\"greek\">τινὲς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span> (Jos., Bell. 1, 311; Just., D. 85, 1 <span class=\"greek\">τινὲς</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:15</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.64\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:64</a>; 7:25, 44; 9:16; 11:37, 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:24</a>.—<span class=\"greek\">τὶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> alguém entre vós, qualquer um de vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:13a</a>, 14, 19. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τινες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>.—<span class=\"greek\">ταῦτά</span> <span class=\"greek\">τινες</span> <span class=\"greek\">ἦτε</span> alguns de vós eram pessoas desse tipo 6:11 (<span class=\"greek\">οὗτος</span> 1b<span class=\"greek\">ζ</span>). <span class=\"greek\">τινές</span> descrito por uma oração relativa (Dionysius Com. [IV a.C.] 11 <span class=\"greek\">εἰσίν</span> <span class=\"greek\">τινες</span> <span class=\"greek\">νῦν</span>, <span class=\"greek\">οὓς</span> … ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:1</a>. <span class=\"greek\">τὶς</span> em 14:47 provavelmente não é original (PDickerson, JBL 116, ’97, 302).</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . com sugestão de inespecificidade num contexto em que uma entidade é especificada até certo ponto <span class=\"greek\">τίς</span> certa pessoa, etc., a respeito de uma pessoa determinada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:5</a>; 10:7; 11:21 (a respeito de um oponente, como UPZ 146, 2 [II a.C.]; Sallust. 12 p. 24, 20; 24.—Artem. 4, 22 p. 214, 20ff <span class=\"greek\">τὶς</span> … <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">καίπερ</span> <span class=\"greek\">εὖ</span> <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπιμνησθήσομαι</span>; Tat. 27, 1 [a respeito de Callimachus]). Pl. <span class=\"greek\">τινές</span> certas pessoas, etc. (Crates, Ep. 32 [p. 82 Malherbe]; Demosth. 25, 40, Ep. 3, 8; Diod S 15, 18, 1; Appian, Bell. Civ. 5, 112 §470 ‘certas’ pessoas que haviam conspirado para causar perturbação; Iambl., Myst. 1, 13 p. 43, 2 P.; Sallust. 4 p. 4, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:18</a>; 15:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a>, 19 al.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:9a</a>. Com acréscimo de um nome <span class=\"greek\">ἦν</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἀσθενῶν</span>, <span class=\"greek\">Λάζαρος</span> havia um homem que estava enfermo, chamado L. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:1</a> (começa como uma narrativa que originalmente circulava de modo independente; cf. Alcman 84 Diehl2 <span class=\"greek\">ἦσκέ</span> [=<span class=\"greek\">ἦν</span>] <span class=\"greek\">τις</span> <span class=\"greek\">Καφεὺς</span> <span class=\"greek\">ἀνάσσων</span>=havia outrora alguém, chamado Cafeu, que reinava). O nome é acrescentado também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:7</a>. Com partic. substantivado <span class=\"greek\">τινές</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ταράσσοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:7</a> (cf. Lysias 19, 57 <span class=\"greek\">εἰσί</span> <span class=\"greek\">τινες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">προαναλίσκοντες</span>).</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . Para <span class=\"greek\">εἷς</span> <span class=\"greek\">τις</span> v. <span class=\"greek\">εἷς</span> 3c. Para <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> v. <span class=\"greek\">εἰ</span> 7. <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> (TestAbr B 13 p. 118, 7 [Stone p. 84]; Just., D. 46, 1 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τινε</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:3a</a>; 24:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:51</a> al.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:41</a> (Hab 1:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:10</a>; 10:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:1</a>, 15; 4:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:20</a>; 22:18f. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> se alguém … não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:3</a>, 5; 15:6; se ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a>. <span class=\"greek\">τὶς</span> com uma negativa, ninguém, nenhuma pessoa <span class=\"greek\">οὐ</span> … <span class=\"greek\">τὶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:28</a>. <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">τὶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27</a>; 12:19. <span class=\"greek\">οὔτε</span> … <span class=\"greek\">τὶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:21</a>. <span class=\"greek\">οὐ</span> … <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:12</a>. <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> para que ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:15</a>; 16:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:20</a>; 11:16a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:11</a> al. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μή</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>. <span class=\"greek\">ὥστε</span> <span class=\"greek\">μὴ</span> … <span class=\"greek\">τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a>.</p><p class=\"entry-text\"><span class=\"hebrew\">ד</span> . O partic. que se relaciona diretamente com o pron. indef. é acrescentado com o art. <span class=\"greek\">πρός</span> <span class=\"greek\">τινας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πεποιθότας</span> a alguns que depositavam sua confiança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:9</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>. Mas também aparece sem o art.: <span class=\"greek\">τινῶν</span> <span class=\"greek\">λεγόντων</span> quando alguns falavam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:5</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a>, 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:28</a>.</p><p class=\"entry-text\"><span class=\"hebrew\">ה</span> . em correspondência <span class=\"greek\">τὶς</span> … <span class=\"greek\">ἕτερος</span> <span class=\"greek\">δέ</span> alguém … e outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:4</a>. <span class=\"greek\">τινὲς</span> (<span class=\"greek\">μὲν</span>) … <span class=\"greek\">τινὲς</span> (<span class=\"greek\">δέ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:7f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:15</a> (<span class=\"greek\">τινὲς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">τινὲς</span> <span class=\"greek\">δέ</span> como Diod S 12, 41, 6; Ar. 8, 2).</p><p class=\"entry-text\"><span class=\"hebrew\">ו</span> . cada um <span class=\"greek\">καθώς</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἄξιός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">κατοικεῖν</span> conforme cada um merece habitar Hs 8, 2, 5a. Cf. 8, 4, 2. B-D-F §301, 2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τὶ</span>, <span class=\"greek\">τινά</span></p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . alguma coisa, qualquer coisa <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφός</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">τι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:23</a>. Cf. 20:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:23</a>; 9:22; 13:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:40</a>; 11:54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:29a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:31</a> al.—Com gen. partitivo (Diod S 20, 39, 3 <span class=\"greek\">τινὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀφηρπασμένων</span>=parte daquilo que fora tomado [pelo inimigo]; Just., D. 2, 4 <span class=\"greek\">τὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">εὐδαιμονίαν</span> <span class=\"greek\">συντελούντων</span> algo que contribui para a felicidade) <span class=\"greek\">τὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπαρχόντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:32</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:27</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀγαθοῦ</span> Hs 5, 3, 3.</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . em enunciados negativos, não (nem) alguma coisa = nada <span class=\"greek\">οὔτε</span> … <span class=\"greek\">τὶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:8</a>. <span class=\"greek\">οὐδὲ</span> … <span class=\"greek\">τὶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:7</a> (TestJob 11:12; cf. JosAs 10:20 <span class=\"greek\">μηδὲ</span> … <span class=\"greek\">τινό</span>).</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . <span class=\"greek\">τινὰ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">τινὰ</span> <span class=\"greek\">δέ</span> uns … outros (em referência a <span class=\"greek\">πρόβατα</span> e, portanto, neutro) Hs 6, 2, 2.</p><p class=\"entry-text\"><span class=\"hebrew\">ד</span> . Sobre <span class=\"greek\">εἴ</span> <span class=\"greek\">τι</span> v. <span class=\"greek\">εἰ</span> 7.</p><p class=\"entry-text\"><span class=\"hebrew\">ה</span> . <span class=\"greek\">εἶναί</span> <span class=\"greek\">τι</span> ser ou representar alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:7</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">δοκεῖ</span> <span class=\"greek\">τις</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">τι</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὤν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:3</a> (v. 2 abaixo e v. W-S. §26, 3).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. algum, qualquer, certo, embora frequentemente omitido na tradução para o inglês; empregado com</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . um subst. <span class=\"greek\">τὶς</span>: <span class=\"greek\">ἱερεύς</span> <span class=\"greek\">τις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:5</a>; 10:31. <span class=\"greek\">ἀνήρ</span> (uma narrativa começa dessa maneira Syntipas p. 16, 4; 30, 3; 46, 16; 57, 1; Just., D. 81, 4 [a respeito de João]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:2</a>; 8:9a; 14:8. <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12</a> (JosAs 28:4). <span class=\"greek\">κώμη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:12</a> (Just., A I, 34, 2). Cf. 7:2, 41; 18:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:7</a>.—<span class=\"greek\">τὶ</span>: <span class=\"greek\">ὕδωρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36</a>. <span class=\"greek\">σκεῦος</span> 10:11.</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . um nome próprio (X., Hell. 5, 4, 3; Jos., Ant. 12, 160; Ar. 10, 1 <span class=\"greek\">Ἥφαιστόν</span> <span class=\"greek\">τινα</span>; Just., A I, 26, 4 <span class=\"greek\">Μένανδρον</span> … <span class=\"greek\">τινά</span>; Ath. 12, 1 <span class=\"greek\">Μίνως</span> <span class=\"greek\">τις</span>) <span class=\"greek\">Σίμωνά</span> <span class=\"greek\">τινα</span> certo Simão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:5f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:21</a>. <span class=\"greek\">Σίμων</span> <span class=\"greek\">τις</span> AcPlCor 1:2. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:16</a>; 22:12; 25:19b.</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . um adj. ou pron. adjetivo <span class=\"greek\">μέγας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:9b</a>. <span class=\"greek\">ἕτερός</span> <span class=\"greek\">τις</span> v. 34 (GrBar 6:6; Just., D. 128, 4; Mel., P. 26, 180). <span class=\"greek\">τὶς</span> <span class=\"greek\">ἕτερος</span> Papias (2, 4). <span class=\"greek\">τὶς</span> <span class=\"greek\">ἄλλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:4</a> (TestAbr B 6 p. 110, 7 [Stone p. 68] <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span>; TestJob 11:2 <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">τινές</span>; Just., D. 6, 1 <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span>). <span class=\"greek\">τινὲς</span> <span class=\"greek\">ἄλλοι</span> (Diod S 5, 81, 4 <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">τινὲς</span> [<span class=\"greek\">τ</span>. <span class=\"greek\">ποιητῶν</span>]; Jos., Ant. 8, 248; Just., D. 84, 4 <span class=\"greek\">ἄλλαι</span> <span class=\"greek\">τινές</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:2</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀγαθόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>; Hs 2:10. <span class=\"greek\">ἀσφαλές</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:26</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.40\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:40</a>.—Em enunciados neg. (TestAbr A 8 p. 86, 3 [Stone p. 20]) não algum = nenhum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. servindo para atenuar ou intensificar</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . para atenuar uma expressão demasiado definida (Just., D. 48, 1 [<span class=\"greek\">λόγος</span>] … <span class=\"greek\">παράδοξός</span> <span class=\"greek\">τις</span> … <span class=\"greek\">δοκεῖ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἶναι</span> [tua afirmação], a meu juízo, não faz muito sentido; Diod S 1, 1, 3; Appian, Bell. Civ. 1, 15 §65 <span class=\"greek\">οἷά</span> <span class=\"greek\">τινες</span> <span class=\"greek\">δορυφόροι</span>=como uma espécie de guarda pessoal) <span class=\"greek\">ἀπαρχήν</span> <span class=\"greek\">τινα</span> uma espécie de primícias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:18</a> (Appian, Bell. Civ. 3, 39 §162 <span class=\"greek\">τὶς</span> <span class=\"greek\">μετάνοια</span>=algo semelhante ao remorso; 3, 77 §314 <span class=\"greek\">συγγνώμη</span> <span class=\"greek\">τις</span>=uma espécie de perdão).—Assim talvez <span class=\"greek\">δύο</span> <span class=\"greek\">τινὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span> vários discípulos, talvez dois <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:18</a> (cf. Appian, Bell. Civ. 2, 59 §245 <span class=\"greek\">δύο</span> <span class=\"greek\">τινάς</span>=alguns [navios], cerca de dois; Jos., Ant. 16, 274). Mas a expressão em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:23</a> <span class=\"greek\">τινὰς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑκατονταρχῶν</span> significa certamente dois, que simplesmente não podem ser identificados mais precisamente (v. W-S. §26, 1b; Rob. 742; Mlt-Turner 195).</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . com adjetivos de qualidade e quantidade para intensificar a ênfase retórica <span class=\"greek\">φοβερά</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἐκδοχὴ</span> <span class=\"greek\">κρίσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a>. <span class=\"greek\">βραχύ</span> <span class=\"greek\">τι</span> (somente) um pouco 2:7, 9 (Ps 8:6).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. a respeito de uma quantidade indefinida que, entretanto, não deixa de ter importância, algum, considerável <span class=\"greek\">χρόνον</span> <span class=\"greek\">τινά</span> (Diod S 13, 75, 6 <span class=\"greek\">μετά</span> <span class=\"greek\">τινα</span> <span class=\"greek\">χρόνον</span>; Jos., Ant. 8, 398) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:7</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:11</a>, 13. <span class=\"greek\">μέρος</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">τινές</span> vários (Appian, Bell. Civ. 2, 49 §202 <span class=\"greek\">ἱππεῖς</span> <span class=\"greek\">τινες</span>; Just., D. 50, 2 <span class=\"greek\">λόγους</span> <span class=\"greek\">τινάς</span>; Ath. 23, 1 <span class=\"greek\">τινὰς</span> … <span class=\"greek\">ἐνεργείας</span>) <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τινάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:19</a>; 10:48; 15:36. <span class=\"greek\">γυναῖκές</span> <span class=\"greek\">τινες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:2</a>; 17:5f al.—Sobre sua posição na oração, v. W-S. §26, 4; B-D-F §473, 1; Rob. 743.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> referência a alguém de destaque, uma pessoa importante <span class=\"greek\">τὶς</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τις</span> ser uma pessoa importante, ser alguém (Eur., El. 939; Theocr. 11, 79; Herodas 6, 54; Epict. 3, 14, 2, Ench. 13; Lucian, Lexiph. 22, Adv. Indoct. 1; Tat. 16, 2 <span class=\"greek\">εἶναί</span> <span class=\"greek\">τινες</span>; PGM 13, 288 <span class=\"greek\">ἐγώ</span> <span class=\"greek\">εἰμί</span> <span class=\"greek\">τις</span>) <span class=\"greek\">λέγων</span> <span class=\"greek\">εἶναί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἑαυτόν</span> alegando ser alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36</a>; IEph 3:1 (assim também <span class=\"greek\">τὶ</span>; v. 1a<span class=\"greek\">β</span><span class=\"hebrew\">ה</span> acima; antônimo s.v. <span class=\"greek\">οὐδείς</span> 2b<span class=\"greek\">β</span>).—DELG. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τίτιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τίτιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (CIL III, 3053; 6010, 223; XII, 4141; Jos., Ant. 16, 270) Tício, um <span class=\"greek\">σεβόμενος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (<span class=\"greek\">σέβω</span> 1b) em Corinto, cujo sobrenome era Justo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:7</a> (v.l. <span class=\"greek\">Τίτος</span>; muitos mss. omitem inteiramente essa metade do nome e trazem simplesmente <span class=\"greek\">Ἰούστου</span>).—EGoodspeed, JBL 69, ’50, 382f identifica Tício Justo com Gaio (<span class=\"greek\">Γάϊος</span> 3; v. comentários).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίτλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίτλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (empréstimo lat.=titulus: inscrições [Hahn 231, 10, com literatura; Hatch 143f]; papiros tardios; Jer 21:4 em Aq., Sym., Theod.; Mel., P. 95, 727) inscrição, aviso na cruz, que indicava a razão da condenação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:19f</a> (sobre esse costume, v. Sueton., Calig. 32, Domit. 10; Cass. Dio 54, 8; também a carta das igrejas de Lyon e Vienne: Eus., HE 5, 1, 44). P-FRegard, Le titre de la Croix d’après les Év.: RevArch 28, 1928, 95–105.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τίτος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τίτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Polyb.; Diod S 11, 51, 1; 15, 23, 1; 16, 40, 1 et al.; inscrições, papiros; Jos., Ant. 14, 229f) Tito.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> amigo e colega de Paulo, mencionado em nossa literatura somente nas cartas de Paulo. Como cristão gentio, acompanhou Paulo a uma reunião em Jerusalém; Paulo não o mandou circuncidar, embora os judaizantes exigissem que o fizesse <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:1</a>, 3. Mais tarde efetuou uma reconciliação entre Paulo e a igreja de Corinto, quando esta parecia perdida para o apóstolo, e organizou uma coleta: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:13</a>; 7:6, 13f; 8:6, 16, 23; 12:18; subscrição.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:10</a> menciona uma viagem de Tito à Dalmácia. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:4</a> o apóstolo o deixou, seu <span class=\"greek\">γνήσιον</span> <span class=\"greek\">τέκνον</span>, em Creta, para organizar as igrejas de lá (v. v. 5); v. também o título e a subscrição de Tit quanto ao nome. <span class=\"greek\">Τίτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Λουκᾶν</span> AcPl Ha 11, 16 (Aa I, 116, 16f); AcPl Ant 13, 13 (Aa I, 237, 1).—AJülicher, RE XIX 1907, 798–800; CBarrett, MBlack Festschr. ’69, 1–18. Literatura s.v. <span class=\"greek\">Τιμόθεος</span> (Pölzl 103ff) e <span class=\"greek\">Ἰωάν</span>(<span class=\"greek\">ν</span>)<span class=\"greek\">ης</span> 6.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> de sobrenome Justo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:7</a> v.l.; v. <span class=\"greek\">Τίτιος</span>.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιτρώσκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιτρώσκω</span> 1 aor. <span class=\"greek\">ἔτρωσα</span> LXX. Pass. fut. <span class=\"greek\">τρωθήσομαι</span> LXX; aor. 2 sing. <span class=\"greek\">ἐτρώθης</span> Is 57:10 Sym.; perf. <span class=\"greek\">τέτρωμαι</span> 3 Km 22:34, partic. <span class=\"greek\">τετρωμένος</span> (Hom.+; inscrições, LXX, Philo; Jos., Bell. 2, 526, Ant. 7, 128) infligir uma ferida, ferir, lesar, danificar, em linguagem figurada de dano à vida interior <span class=\"greek\">τετρωμένος</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">διάνοιαν</span> ferido na mente (<span class=\"greek\">διάνοια</span> 1) GPt 7:26 (cf. 2 Macc 3:16 <span class=\"greek\">τιτρώσκεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span>; Diod S 17, 112 <span class=\"greek\">τετρωμένος</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>; Herodian 1, 8, 7; Philo).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοί</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοί</span> (propriamente dat. ético de <span class=\"greek\">συ</span>, L-S-J-M, v. também Denniston 537; Schwyzer I 602) partícula enclítica (Hom.+; LXX; Jos., Ant. 15, 374; 16, 319; Just., A I, 4, 8 <span class=\"greek\">καὶ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">τοι</span>) marcador de ênfase na fidedignidade de uma afirmação, deixa-me dizer-te, certamente, em nossa literatura somente na fórmula de transição <span class=\"greek\">πέρας</span> <span class=\"greek\">γέ</span> <span class=\"greek\">τοι</span> e, além disso, ademais (<span class=\"greek\">πέρας</span> 3) B 5:8; 10:2; 12:6; 15:6, 8; 16:3.—Para <span class=\"greek\">μέν</span> <span class=\"greek\">τοι</span> v. <span class=\"greek\">μέντοι</span>.—DELG s.v. <span class=\"greek\">το</span>-1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιγαροῦν</h1><div class=\"entry-meta\"><span>partícula inferencial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοιγαροῦν</span> (sobre a forma, v. Schwyzer I 560; Denniston 114) (Soph., Hdt.+; PTebt 315, 14 [II d.C.]; PGiss 3, 7; Sb 6222, 12; LXX; En 102:9; GrBar 4:16; Philo, Virt. 202; Jos., Bell. 4, 168, Ant. 10, 10, C. Ap. 2, 178; Just., Mel.) partícula que introduz uma inferência, precisamente por essa razão, então, portanto (em primeira posição, como na maioria dos escritores antigos, exceto Hippocrates e ocasionalmente Lucian, v. Denniston 566–68) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:8</a>; 1 Cl 57:4, 6 (Pr 1:26, 31). Numa exortação (Achilles Tat. 7, 11, 3; Jos., C. Ap. 2, 201; GrBar 4:16; Just., D. 55, 3; 65, 7; 134, 2; Mel., P. 59, 428) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a> (aqui P46 traz <span class=\"greek\">τοίγαρ</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοίνυν</h1><div class=\"entry-meta\"><span>partícula inferencial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοίνυν</span> (Pind., Hdt.+) partícula que introduz uma inferência, por conseguinte, assim, pois bem, de fato, como segunda palavra de sua oração (a posição usual, assim Hdt., Demosth. et al. [v. Denniston 568–77 sobre a posição e o aspecto vivo, conversacional de <span class=\"greek\">τ</span>.]; POxy 902, 10; 1252 verso, 18; Wsd 1:11; Job 8:13; 36:14; En 101:1; TestAbr A 1 p. 77, 11 [Stone p. 2]; JosAs 6:5 [1:1, 7 al. cod. A]; ApcrEzk; Jos., Ant. 2, 67; 14, 32; Ar., Just., Ath.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:24</a> v.l.; Dg 3:2. No início de sua oração (somente em escritores tardios, p. ex. Sext. Emp., Math. 8, 429; IG IV, 620, 13; POxy 940, 3; Is 3:10; 5:13; 27:4; 33:23; TestJob 41:5; Mel.) <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπόδοτε</span> pois bem, devolvei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:25</a> (com imper.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:13</a> (com subj. hortativo); 1 Cl 15:1 (com subj. hort.)—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιόσδε, άδε, όνδε</h1><div class=\"entry-meta\"><span>adjetivo demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοιόσδε</span>, <span class=\"greek\">άδε</span>, <span class=\"greek\">όνδε</span> (Hom., Hdt. et al.; 2 Macc 11:27; 15:12; TestSol 22:2 B; Jos., Ant. 17, 142; 209) tal como este, desta espécie, referindo-se ao que segue e com sugestão de aspecto incomum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>.—DELG s.v. <span class=\"greek\">τοῖο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοιοῦτος, αύτη, οῦτον</h1><div class=\"entry-meta\"><span>adjetivo correlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοιοῦτος</span>, <span class=\"greek\">αύτη</span>, <span class=\"greek\">οῦτον</span> (esta forma do neutro predomina nos escritores áticos; também JosAs 6:7; 13:11; 1 Esdr 1:19; Jos., C. Ap. 1, 12; 2, 222; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:5</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:25</a> D; Just., A I, 12, 4; Tat. 15, 2) e <span class=\"greek\">οῦτο</span> (PCairZen 379, 8; 482, 13 [III a.C.]; POsl 17, 9 [136 d.C.]; 1 Cl 43:1; Mel., HE 4, 26, 13) adj. correlativo relativo a ser semelhante a alguma pessoa ou coisa mencionada num contexto, de tal espécie, tal como este, semelhante a tal (Hom.+).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> correlativo <span class=\"greek\">οἷος</span> … <span class=\"greek\">τοιοῦτος</span> (X., Mem. 2, 6, 12; Lucian, Dial. Deor. 4, 4; Sir 49:14; Just., A II, 14, 2 <span class=\"greek\">τοιαῦτα</span>, <span class=\"greek\">ὁποῖα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.48\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:48ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:11b</a>. <span class=\"greek\">τοιούτους</span> <span class=\"greek\">ὁποῖος</span> (Jos., Ant. 7, 385) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> adj.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. empregado com um substantivo</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . com o art., principalmente atributivo (GrBar 7:5; Ar. 11, 2; Just., A I, 12, 4; Tat. 15, 2; Mel., HE 4, 26, 6; Ath. 7, 1) <span class=\"greek\">ἓν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοιούτων</span> <span class=\"greek\">παιδίων</span> uma criança como esta (conforme indicado no v. 36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:37</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">ἄνθρωπον</span> tal homem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:3</a> (cf. v. 2). <span class=\"greek\">ἡ</span> <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">παρθένος</span> AcPl Ox 6, 15f (<span class=\"greek\">ἡ</span> <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">αἰδὼς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρθένου</span> Aa I 241, 15). <span class=\"greek\">τῆς</span> <span class=\"greek\">τοιαύτης</span> <span class=\"greek\">διακονίας</span> IPhld 10:2 (cf. v. 1). <span class=\"greek\">οἱ</span> <span class=\"greek\">τοιοῦτοι</span> <span class=\"greek\">δίκαιοι</span> 2 Cl 6:9 (cf. v. 8). Pred. <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τοιαῦται</span> tais são os milagres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:2</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">γνῶσις</span> <span class=\"greek\">τοιαύτη</span> o conhecimento é desta espécie (conforme descrito no que segue) B 19:1.</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . sem o artigo (TestAbr A 11 p. 89, 19 [Stone p. 26] <span class=\"greek\">ἐν</span> <span class=\"greek\">τοιαύτῃ</span> <span class=\"greek\">δόξῃ</span>; JosAs 6:7; 13:11; GrBar 1:2; Ar. 13:1; Just., A I, 9, 5; Mel., P. 20, 137; Ath. 22, 1) <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τοιαύτην</span> tal poder <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:8</a>.—18:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:4</a>, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:26</a>; 13:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:16</a>. AcPlCor 1:9 <span class=\"greek\">ἔστι</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">λέγουσιν</span> … <span class=\"greek\">τοιαῦτα</span> o que dizem … é o seguinte</p><p class=\"entry-text\"><span class=\"hebrew\">ג</span> . <span class=\"greek\">τοι</span>. pode ter seu significado esclarecido por uma oração relativa <span class=\"greek\">τοιαύτη</span> <span class=\"greek\">πορνεία</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span> (subentende-se <span class=\"greek\">ἀκούεται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a>. <span class=\"greek\">τοιοῦτος</span> <span class=\"greek\">ἀρχιερεύς</span>, <span class=\"greek\">ὅς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:1</a> (Dio Chrys. 15 [32], 7 <span class=\"greek\">χορὸς</span> <span class=\"greek\">τοιοῦτος</span> … , <span class=\"greek\">ὅς</span>). <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">τοιοῦτοι</span> <span class=\"greek\">οἵτινες</span> B 10:3–5.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τοιοῦτος</span> <span class=\"greek\">ὤν</span> (Just., A I, 43, 8; Ath. 29, 1) visto que sou o tipo de pessoa (que presume fazer um apelo) Phlm 9 (seguido de <span class=\"greek\">ὡς</span>=na minha condição de; Andoc., Alcibiades 16). <span class=\"greek\">τοιούτου</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὄντος</span> visto que tu (Cristo) estás tão (abatido) AcPl Ha 7, 31. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοιούτους</span> <span class=\"greek\">ζητεῖ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προσκυνοῦντας</span> <span class=\"greek\">αὐτόν</span> o Pai procura tais pessoas para o adorarem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:23</a> (duplo acus. como Vett. Val. 315, 20 <span class=\"greek\">τινὰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τοιούτους</span>; Jos., Ant. 12, 281). O emprego pleonástico de <span class=\"greek\">τοι</span>. após um relativo deve-se à influência semítica (Ex 9:18, 24; 11:6) <span class=\"greek\">θλῖψις</span> <span class=\"greek\">οἵα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">τοιαύτη</span> tribulação tal como nunca se viu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:19</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> subst.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. muito predominantemente com o art. (B-D-F §274; Rob. 771)</p><p class=\"entry-text\"><span class=\"hebrew\">א</span> . a respeito de pessoas <span class=\"greek\">ὁ</span> <span class=\"greek\">τοιοῦτος</span> tal pessoa; seja de modo que se pense num indivíduo determinado com características especiais, seja no sentido de qualquer portador de certas qualidades determinadas (Just., D. 47, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:6f</a>; 10:11a; 12:2, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:11</a>. Pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">τοιοῦτοι</span> (Aeschyl., Thu. et al.; TestAsh 2:9; 4:5; ApcEsdr 1:18 p. 25, 12 Tdf.; Tat. 2, 2; Mel., HE 4, 26, 9; Ath. 34, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:28</a>; 16:16 al.</p><p class=\"entry-text\"><span class=\"hebrew\">ב</span> . a respeito de coisas <span class=\"greek\">τὰ</span> <span class=\"greek\">τοιαῦτα</span> tais coisas ou semelhantes, coisas desse gênero (X., Cyr. 1, 2, 2 um catálogo de vícios que termina <span class=\"greek\">καὶ</span> … <span class=\"greek\">τἄλλα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">ὡσαύτως</span>; semelhantemente, Ael. Aristid. 37, 27 K.=2 p. 27 D.; Plut., Mor. 447a; GrBar 13:4; Just., D. 18, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:32</a>; 2:2f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:27</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοιούτοις</span> em tais casos, em tais circunstâncias (X., Cyr. 5, 4, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. sem o art. <span class=\"greek\">τοιαῦτα</span> tais coisas (Socrat., Ep. 14, 6 [p. 256 Malherbe]; TestNapht 9:1; GrBar 1:3; Ar. 8, 5; Just., D. 6, 1; Tat. 21, 1; Mel., P. 74, 544) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:9</a>; 13:2 v.l. (em lugar de <span class=\"greek\">ταῦτα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:14</a>.—DELG s.v. <span class=\"greek\">τοῖο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0359-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῖχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοῖχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+) parede, em expressão de denúncia <span class=\"greek\">τοῖχε</span> <span class=\"greek\">κεκονιαμένε</span> parede caiada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a> (desde RSmend, Ezech. 1880, costuma-se comparar aqui Ezk 13:10).—DELG s.v. <span class=\"greek\">τεῖχο</span>. M-M.</p></section></article>"};
